"""Informe reproducible sobre los originales, sin modificarlos."""
from pathlib import Path
from html import escape
from reportlab.platypus import SimpleDocTemplate, Paragraph, Spacer, PageBreak, KeepTogether, HRFlowable
from reportlab.lib.styles import ParagraphStyle
from reportlab.lib.colors import HexColor
from reportlab.lib.pagesizes import A4
from reportlab.pdfbase import pdfmetrics
from reportlab.pdfbase.ttfonts import TTFont

ROOT = Path(__file__).resolve().parents[1]
OUT = ROOT / 'output' / 'pdf' / 'Informe_errores_diagramas.pdf'
OUT.parent.mkdir(parents=True, exist_ok=True)
for name, filename in [('Arial','arial.ttf'),('Arial-Bold','arialbd.ttf')]:
    pdfmetrics.registerFont(TTFont(name, str(Path('C:/Windows/Fonts') / filename)))
pdfmetrics.registerFontFamily('Arial',normal='Arial',bold='Arial-Bold')
INK=HexColor('#1c2835'); BLUE=HexColor('#235b72'); MUTED=HexColor('#56616d')
styles={
 'title':ParagraphStyle('title',fontName='Arial-Bold',fontSize=27,leading=32,textColor=INK,spaceAfter=16),
 'h1':ParagraphStyle('h1',fontName='Arial-Bold',fontSize=21,leading=26,textColor=INK,spaceAfter=13),
 'h2':ParagraphStyle('h2',fontName='Arial-Bold',fontSize=12,leading=16,textColor=BLUE,spaceAfter=6),
 'body':ParagraphStyle('body',fontName='Arial',fontSize=10.5,leading=15,textColor=INK,spaceAfter=8),
 'small':ParagraphStyle('small',fontName='Arial',fontSize=9,leading=12,textColor=MUTED,spaceAfter=7),
 'tag':ParagraphStyle('tag',fontName='Arial-Bold',fontSize=8.5,leading=11,textColor=MUTED,spaceAfter=5),
}
story=[]
def p(text,style='body'): return Paragraph(text,styles[style])
def add(text,style='body'): story.append(p(text,style))
def page(title,subtitle=None):
    if story: story.append(PageBreak())
    add(title,'h1')
    if subtitle: add(subtitle,'small')
    story.append(HRFlowable(width='100%',thickness=1,color=BLUE,spaceAfter=16))
def finding(code,title,kind,where,seen,why,fix):
    parts=[p(f'{code} | {title}','h2'),p(kind.upper(),'tag'),p('<b>Dónde:</b> '+escape(where),'small'),p('<b>Qué se observa:</b> '+escape(seen)),p('<b>Por qué:</b> '+escape(why)),p('<b>Corrección:</b> '+escape(fix)),Spacer(1,12)]
    story.append(KeepTogether(parts))

add('Revisión de diagramas\n<br/>Cajero Automático','title')
add('Errores, ubicación y explicación','h1')
add('13 de noviembre de 2026 | Informe sobre la versión original','small')
story.append(Spacer(1,14))
add('<b>La base del trabajo está: hay contexto, procesos principales, cinco casos de uso, ocho clases y cinco secuencias.</b> Los problemas más importantes están en el balanceo de los DFD, las relaciones que faltan entre clases y la coherencia de los mensajes de secuencia.')
add('Este informe se refiere a los archivos de <b>TrabajoCorregido</b>, aunque el nombre de esa carpeta diga “corregido”. Las modificaciones se encuentran en <b>TrabajoCorregidoCodex</b>. Los originales se conservaron.')
add('Carpeta original de referencia:<br/>'+escape(str(ROOT.parent/'TrabajoCorregido')),'small')
add('Cada hallazgo indica el archivo relativo a esa carpeta y los elementos que permiten localizarlo en StarUML. Las coordenadas se usan solo cuando ayudan a identificar una activación; no son números de línea del archivo JSON.')
add('Criterios utilizados','h2')
add('<b>Error confirmado:</b> incumplimiento concreto de la consigna o del flujo representado.<br/><b>Inconsistencia:</b> dos diagramas o responsabilidades no coinciden.<br/><b>Aclaración:</b> el modelo admite interpretaciones y necesita documentarse; no se presenta como una prohibición de UML.<br/><b>Pendiente:</b> falta un entregable, no una flecha dentro de un diagrama.')
add('Exclusiones solicitadas','h2')
add('No se exige identificar D2 y D3 ni reproducir relaciones de una “sección 5” no aplicable. Sí se conserva la exigencia explícita de herencia desde Operacion y de relaciones con multiplicidades. No se califican las preferencias visuales como errores de notación.')
add('Guía de lectura','h2')
add('2. Contexto y Nivel 0 · 3-4. Descomposiciones DFD · 5. Clases · 6. Casos de uso · 7. Autenticación · 8. Consulta y transferencia · 9. Extracción y cierre · 10. Entregables y alcance.','small')

page('Contexto y DFD Nivel 0','Puntos 1 y 2 de la consigna. La presencia de los tres terminadores es correcta.')
finding('D01','Flujo sin nombre en el contexto','Error confirmado','DiagramaContexto/DiagramaDeContexto.mdj; flecha Cliente -> Cajero Automatico sin etiqueta.','Hay una entrada del Cliente sin nombre, además de Datos de tarjeta, Opción elegida, Monto, CBU destino y Confirmación.','La consigna exige nombrar todos los flujos. Una flecha sin nombre no permite saber qué información entra ni comprobar su equivalencia en el Nivel 0. No puede asegurarse que sea el PIN solo por su posición.','Identificar el contenido de esa entrada. En la versión corregida, las credenciales están definidas en el diccionario de datos y se mantienen entre niveles.')
finding('D02','Dos flujos sin identificar en Nivel 0','Error confirmado','DFD/DFDNivel0.mdj; Autenticar Usuario -> Cliente y Red Central -> Extraer Efectivo.','Las dos flechas existen pero carecen de nombre.','No se sabe si la primera comunica un menú, un rechazo u otro resultado; la segunda tampoco identifica la respuesta del débito. Esto impide verificar datos y balanceo.','Nombrar las respuestas de autenticación y débito, con una composición explícita en el diccionario.')
finding('D03','Entradas y salidas del contexto que desaparecen','Error confirmado','Comparar DiagramaDeContexto.mdj con DFD/DFDNivel0.mdj, alrededor de Autenticar Usuario.','El contexto tiene Cajero -> Sucursal: Solicitud de validación de tarjeta y Red Central -> Cajero: Confirmación de PIN. En Nivel 0 no hay las correspondientes flechas Autenticar Usuario -> Sucursal ni Red Central -> Autenticar Usuario.','Descomponer un proceso debe conservar sus intercambios con el exterior. No alcanza con mantener los mismos actores o escribir “Valida pin” en la solicitud: esa flecha tiene sentido opuesto al de la respuesta.','Restituir ambos intercambios y comprobar terminador, sentido y contenido. Los nombres agrupados entre niveles requieren una definición que demuestre su equivalencia.')

page('DFD Nivel 1: origen de los datos','Archivo común: DFD/DFDNivel1.mdj. Los cinco bloques funcionales están reconocidos.')
finding('D04','Conexiones directas con un almacén','Error de frontera / notación DFD','Bloque Autenticar Usuario; Sucursal y Red central conectados directamente a Usuario_Cliente.','Hay cuatro flujos directos: cada terminador envía “Solicita datos” al almacén y recibe “Devuelve datos”.','Si Usuario_Cliente es interno al cajero, esas lecturas deben pasar por un proceso del sistema. Si pertenece a Sucursal o a la Red Central, se está exponiendo el interior de otro sistema como si fuera parte del cajero. En ambos casos la frontera queda mal definida.','Representar la consulta a cada sistema externo mediante los procesos de validación. No incorporar su base privada como almacén interno del cajero.')
finding('D05','El PIN aparece sin una entrada del Cliente','Error de flujo de datos','Bloque 1; 1.3 Solicitar PIN -> 1.4 Validar PIN, flujo “Ingresa PIN”.','Se solicita el PIN al Cliente, pero no hay una flecha de regreso desde Cliente que aporte el PIN en ese nivel.','Solicitar un dato no produce el valor ingresado. El proceso 1.4 recibe información cuyo origen no está representado. En Nivel 2 sí aparece Cliente -> Recibir PIN, por lo que tampoco se mantiene esa frontera entre niveles.','Incluir la captura del PIN y conservarla en la descomposición. En la versión corregida se documenta el intercambio agregado de credenciales.')
finding('D06','El CBU destino aparece sin ser recibido','Error de flujo de datos','Bloque 4; 4.2 Solicitar CBU destino -> 4.3 Recibir CBU destino.','El flujo se llama “CBU destino”, pero no hay Cliente -> 4.3 aportando ese valor.','El proceso que pide el CBU no puede inventar el CBU del destinatario. Faltan la entrada efectiva y su trazabilidad hasta la instrucción de transferencia.','Hacer explícito el dato ingresado por el Cliente o agruparlo en una solicitud de transferencia cuya composición incluya CBU, monto y confirmación.')

page('DFD: nombres, lecturas y detalle','No todos los problemas de Nivel 1 o 2 son requisitos adicionales de la consigna: también se revisa la coherencia de lo que ya está dibujado.')
finding('D07','Lectura de D1 representada como salida hacia D1','Error de dirección / información faltante','DFD/DFDNivel1.mdj; 5.3 Obtener operaciones de la sesión -> D1 Log de Transacciones.','La flecha hacia D1 dice “Operaciones realizadas durante la sesión”. No existe D1 -> 5.3 devolviendo esas operaciones, aunque 5.3 luego produce “Detalle de operaciones”.','La información almacenada debe salir del almacén para poder generar el ticket. Una solicitud de búsqueda hacia D1 es válida, pero su contenido debe ser el criterio de consulta, no el resultado que se está intentando recuperar.','Separar Consulta de operaciones de sesión hacia D1 y Operaciones de sesión desde D1.')
finding('D08','Siete flechas sin nombre en las descomposiciones','Error confirmado','DFD/DFDNivel1.mdj y DFD/DFDNivel2-1.mdj.','Nivel 1: Cliente -> 4.10 Mostrar comprobante; 5.4 Emitir ticket -> Cliente; Cliente -> 5.1 Solicitar comprobante; 5.1 -> Cliente. Nivel 2: Enviar datos a Sucursal -> Sucursal; Mostrar solicitud de PIN -> Cliente; Enviar PIN a Red Central -> Red Central.','Sin etiqueta no se puede decidir qué transporta cada flecha ni balancearla. En particular, la flecha Cliente -> Mostrar comprobante no demuestra por sí sola estar invertida: podría ser una confirmación, pero no está definida.','Asignar un significado verificable a cada flujo; retirar una flecha solo si no representa un intercambio necesario.')
finding('D09','Descomposición de extracción incompleta','Detalle pendiente, no requisito independiente','DFD/DfdNivel2-3.mdj; diagramas DFDDiagram3.1, DFDDiagram3.2 y DFDDiagram1.','Se desarrollan 3.1 y 3.2, pero el diagrama DFDDiagram1 está vacío.','Un diagrama vacío no aporta una descomposición comprobable. Sin embargo, la consigna transcrita solo exige el DFD Nivel 0: no sería correcto reprobar el trabajo únicamente por no desarrollar todos los niveles 2.','Eliminar vistas vacías o completar las descomposiciones seleccionadas. La carpeta corregida conserva un desarrollo selectivo del débito con fronteras verificables.')

page('Diagrama de clases','Archivo: DiagramaDeClases/DiagramaClases.mdj. Las ocho clases y los tipos básicos de sus miembros sí están presentes.')
finding('C01','Las ocho clases están desconectadas','Error confirmado frente al punto 5','Clases Consulta, Extraccion, Transferencia, Operacion, Cliente, Tarjeta, Cuenta y Sesion.','No hay relaciones UMLGeneralization ni UMLAssociation en el modelo. Por ello tampoco hay multiplicidades en extremos de relaciones.','Tener cajas con métodos no representa la herencia exigida. Tampoco permite saber qué cuenta usa una operación, qué tarjeta participa en una sesión o cuántas operaciones contiene.','Añadir Consulta, Extraccion y Transferencia -> Operacion. Documentar asociaciones/composición y sus multiplicidades. Las cardinalidades concretas son supuestos de diseño, no una reconstrucción de la “sección 5”.')
finding('C02','Contrato polimórfico no representado','Inconsistencia con la solución en capas','Operacion.ejecutar() y clases Consulta, Extraccion y Transferencia.','Operacion no está marcada abstracta; ejecutar() tampoco. Las tres clases concretas no declaran su propia operación ejecutar().','Para el punto 10, Operacion debe ser abstracta y las especializaciones deben redefinir ejecutar(). El diagrama original no expresa ese contrato. Una clase concreta con ese nombre no sería ilegal en UML, pero no refleja la implementación pedida.','Marcar Operacion y ejecutar() como abstractas y declarar las redefiniciones en las tres especializaciones.')
finding('C03','Miembro duplicado y encapsulación incoherente','Error de firma e inconsistencia con el punto 10','Cliente: dos ingresarPIN(); atributos de las ocho clases.','Cliente contiene dos operaciones ingresarPIN con la misma firma. Los atributos se muestran públicos por defecto.','La repetición no constituye una sobrecarga si no cambian los parámetros. La visibilidad pública es válida en UML, pero contradice el diseño con atributos privados solicitado para el código. El guion bajo es una convención de implementación, no una regla general de UML.','Eliminar el duplicado, mantener una única firma y usar visibilidad privada. Las propiedades públicas y los constructores todavía deben implementarse en el proyecto en capas.')

page('Casos de uso','Archivos: CasosDeUso/CasoDeUsoContextual.mdj y CasosDeUso/CasoDeUso.mdj.')
finding('U01','Participación de Red Central incompleta','Inconsistencia entre vistas','Vista general CasoDeUsoGeneral: Autenticar Usuario y actor Red Central.','Red Central no está asociada a la autenticación en la vista general, aunque interviene en la validación del PIN en la secuencia y aparece en la vista individual.','La vista general omite una participación externa que las otras vistas sí atribuyen al mismo caso de uso.','Añadir la asociación Red Central - Autenticar Usuario y mantener Sucursal para validar la tarjeta.')
finding('U02','Extend sin precisar cuándo y dónde ocurre','Especificación incompleta','Relaciones desde Emitir ticket y Devolver Tarjeta hacia las tres operaciones.','Las flechas extend apuntan al caso base, pero no se definieron condición ni puntos de extensión.','La dirección de las flechas es correcta. Lo incompleto es el significado del cierre: una extensión debe indicar dónde se inserta; además, sin condición documentada no se expresa la intención de cerrar solo cuando el usuario lo solicita. La impresión opcional del ticket no vuelve opcional devolver la tarjeta al cerrar.','Definir el punto finDeOperacion y la condición “cliente solicita finalizar sesión”. Distinguir cierre con ticket y sin ticket; en ambos se devuelve la tarjeta.')
finding('U03','Include necesita una interpretación coherente','Aclaración de modelado, no flecha invertida','Consultar Saldo, Extraer Efectivo y Realizar Transferencia -> Autenticar Usuario.','Los tres include apuntan correctamente al comportamiento incluido. Falta aclarar si cada operación exige introducir tarjeta y PIN otra vez o verifica una sesión ya autenticada.','Include expresa incorporación de comportamiento; no es una flecha que signifique simplemente “ocurrió antes”. Puede usarse si Autenticar Usuario verifica o reutiliza la sesión. Otra solución válida sería autenticación como precondición, pero no es la alternativa elegida aquí.','Conservar include, tal como se solicitó, y documentar la reutilización de una sesión autenticada sin repetir el ingreso del PIN en cada operación.')
add('<b>Lo correcto:</b> aparecen cinco casos de uso, tres actores y los actores secundarios a la derecha. No corresponde señalar como errores esos aspectos ni la orientación de include/extend.','small')

page('Secuencia: Autenticar Usuario','Archivo: DiagramaDeSecuencia/DiagramaSecuencia.mdj; diagrama Autenticar Usuario.')
finding('S01','Llamadas que no muestran los datos enviados','Error frente al punto 6','Mensajes introducirTarjeta, ingresarPIN y validarPIN.','Estas llamadas no indican parámetros. validarTarjeta(numero, vencimiento, entidadEmisora), en cambio, sí los muestra.','No se puede comprobar cómo llegan la tarjeta y el PIN a las validaciones. La consigna pide mensajes con parámetros. Esto no significa que un método legítimamente sin argumentos deba inventarlos.','Usar introducirTarjeta(numero, vencimiento, entidadEmisora), ingresarPIN(pin) y validarPIN(numero, pin), coherentes con las respuestas.')
finding('S02','Activaciones terminan antes de la respuesta','Error de representación temporal','Focos de control de Pantalla cajero, SucursalDB y CentralDB.','SucursalDB empieza en y=152 y termina en y=180; confirmarValidez vuelve en y=186. CentralDB va de y=296 a y=324 y confirmarPIN vuelve en y=332. La primera activación de Pantalla cajero termina en y=156, antes de recibir la respuesta de Sucursal.','En la interacción sincrónica representada, la activación debe abarcar el procesamiento y la espera de las llamadas anidadas hasta el retorno correspondiente. Aquí las barras se cortan antes de finalizar ese tramo. Las coordenadas identifican las posiciones guardadas en el original.','Extender las barras hasta las respuestas, anidar las llamadas y cerrar cada activación en el momento que corresponde.')
finding('S03','Solo se muestra el acceso exitoso','Cobertura incompleta, no sintaxis inválida','Final del diagrama, después de confirmarValidez y confirmarPIN.','La secuencia avanza siempre hacia solicitarPIN y muestraMenu; no distingue rechazo de tarjeta ni PIN inválido.','Un escenario principal puede ser válido por sí solo. Sin embargo, no demuestra las alternativas de autenticación ni el contador requerido en el flujo completo del punto 9. No debe confundirse con haber resuelto esa actividad.','La carpeta corregida incluye secuencias separadas de acceso válido, tarjeta rechazada y tres PIN inválidos. Son escenarios de apoyo; no reemplazan un diagrama de actividad.')
add('<b>Lo correcto:</b> están los cuatro participantes solicitados y confirmarValidez/confirmarPIN son retornos. SolicitarPIN o muestraMenu como respuesta a una interacción del Cliente no son automáticamente errores por llamarse acciones.','small')

page('Secuencias: consulta y transferencia','Archivo: DiagramaDeSecuencia/DiagramaSecuencia.mdj. Las responsabilidades deben coincidir con las clases.')
finding('S04','Métodos enviados a la clase equivocada','Inconsistencia entre clases y secuencias','Realizar Transferencia: Transferencia -> Cuenta, agregarOperacion(transferencia). Consultar Saldo: Cliente -> Sesion, seleccionarOperacion().','agregarOperacion pertenece a Sesion, no a Cuenta. seleccionarOperacion está en Cliente, no en Sesion. Además, Cuenta devuelve Boolean a agregarOperacion, mientras el contrato original de Sesion declara retorno Void.','Si una flecha representa la invocación de un método, el receptor debe poder atenderlo. El retorno también debe corresponder al contrato. No basta con que el nombre aparezca en alguna caja del diagrama de clases.','Enviar el registro a Sesion; centralizar la interacción de selección en la presentación y mantener consistentes firmas y respuestas.')
finding('S05','La transferencia solo evidencia un débito','Flujo funcional incompleto','Realizar Transferencia; llamada Transferencia -> Cuenta denominada debitar.','No se muestra una acreditación en destino ni una solicitud completa a la Red Central que incluya CBU y monto. debitar tampoco muestra el monto.','Disminuir el saldo de origen no demuestra una transferencia completa. Si el destino se procesa dentro de un servicio, debe quedar explícita esa responsabilidad y qué datos recibe.','Representar transferir(cbuDestino, monto) y la comunicación con CentralDB, con confirmación o rechazo. El simulador debe tratar débito y crédito como una misma operación.')
finding('S06','Llamada asíncrona y resultado sin llegar al usuario','Incumplimiento e información incompleta','Transferencia: debitar marcado asynchCall. Consulta: mostrarSaldo() enviado de Consulta a sí misma.','Se espera una respuesta al débito, pero la llamada usa el tipo asíncrono. La consulta termina mostrando el saldo mediante una auto-llamada, sin una interacción de salida hacia la pantalla o el Cliente.','La consigna exige llamadas sincrónicas. Una auto-llamada puede ser válida, pero en este escenario no deja visible cómo el resultado alcanza al usuario.','Usar synchCall para las invocaciones y reply para sus retornos. Mostrar el resultado mediante PantallaCajero y la respuesta al Cliente.')

page('Secuencias: extracción y cierre','Archivo: DiagramaDeSecuencia/DiagramaSecuencia.mdj.')
finding('S07','Mensaje genérico y nombres que no coinciden','Inconsistencia de identificación','Extraer Efectivo: primer mensaje Message1 y participante :Extracion.','El inicio no dice qué operación solicita. Aparecen SolicitaAutorizacion, ValidaFondos, DispensarFondos y ObtenerSaldoRestantes, distintos de solicitarAutorizacion, validarFondos, dispensarEfectivo y obtenerSaldoRestante en las clases.','Message1 no comunica intención ni parámetros. Los nombres diferentes dificultan vincular mensajes con métodos; en C# las mayúsculas también forman parte del identificador. La falta de una “c” en Extraccion es otro desajuste.','Nombrar la solicitud con su monto y unificar los nombres de participantes y operaciones con el modelo de clases.')
finding('S08','Tipo de llamada incorrecto para la consigna','Error frente a los puntos 6 y 7','Extraer Efectivo: Debitar(monto). Emitir Ticket y Devolver Tarjeta: ObtenerDetalle() y DevolverTarjeta().','Las tres llamadas están guardadas como asynchCall.','Un mensaje asíncrono no tiene la misma espera de finalización que uno sincrónico. El enunciado pide llamadas sincrónicas y retornos discontinuos; cambiar solo el texto no cambia el tipo de flecha.','Cambiar el tipo del mensaje a synchCall, conservar reply para las respuestas y ajustar las activaciones y el orden del cierre.')
finding('S09','Responsabilidad de cierre poco clara','Inconsistencia entre vistas / diseño','Emitir Ticket y Devolver Tarjeta; Cliente -> Cliente: FinalizarSesion() y Sesion -> Tarjeta: DevolverTarjeta().','La solicitud de finalización queda como auto-llamada del actor. Tarjeta recibe DevolverTarjeta(), pero ese método no existe en su clase.','La auto-llamada no muestra la solicitud entrando al sistema. Además, se atribuye a la entidad Tarjeta una operación que no está en su contrato; expulsar físicamente una tarjeta corresponde normalmente al mecanismo controlado por el cajero. Esta asignación debe explicitarse, no suponerse.','Representar solicitarCierre en PantallaCajero, obtener el detalle mediante Sesion/Operacion y devolver la tarjeta desde la presentación antes de dar por cerrado el flujo.')

page('Qué falta y qué no es un error','Alcance del informe y de la carpeta corregida.')
add('Entregables pendientes','h2')
add('<b>Diccionario de datos (punto 3).</b> No estaba incluido en los doce modelos originales. Se agregó DiccionarioDeDatos.md en TrabajoCorregidoCodex con nombres, descripciones, composiciones y valores admitidos. Es necesario para justificar los flujos agrupados.')
add('<b>Estados de Sesion (punto 8).</b> No se encontró un diagrama de estados en esos doce archivos. Las secuencias de autenticación no sustituyen los estados Iniciada, Autenticando, Validando, Operando, Cerrando y Cerrada. Continúa pendiente en esta carpeta.')
add('<b>Actividad y aplicación (puntos 9 y 10).</b> Continúan fuera de esta corrección: actividad con decisiones e intentos e implementación en capas. El hecho de que una clase tenga métodos dibujados no significa que la aplicación esté implementada.')
add('<b>README (punto 11).</b> La carpeta corregida explica cómo abrir los modelos. Faltan los integrantes y las instrucciones de ejecución de una aplicación cuando exista. No se presenta como cumplimiento completo del punto 11.')
add('Aclaraciones para no corregir algo que está bien','h2')
add('Los nombres de <b>clases</b> como Cliente o Cuenta no se subrayan por ser clases. El subrayado identifica instancias en la notación de objetos. La frase de la consigna sobre “OBJETOS” no convierte automáticamente las ocho clases en objetos ni permite exigir subrayado a sus nombres.')
add('Las asociaciones concretas y sus multiplicidades necesitan una justificación del dominio. No existe una única combinación correcta deducible de la referencia equivocada a la “sección 5”. Los supuestos adoptados se explican en README.md.')
add('Los rótulos “Efectivo dispensado” o “Tarjeta devuelta” en un DFD deben leerse como información de resultado si se usa un DFD lógico. El transporte físico de billetes o tarjetas no se modela como un dato. El diccionario de la corrección aclara esta interpretación.')
add('Fuentes y comprobación','h2')
add('Revisión directa de los doce archivos .mdj de TrabajoCorregido; comparación con la consigna transcrita y con TrabajoCorregidoCodex. Bibliografía proporcionada: UML 2.5 - Iniciación, ejemplos y ejercicios corregidos, como marco para relaciones de casos de uso, clases/objetos y diagramas de interacción. Las reglas de balanceo DFD se evalúan por separado: DFD no es un diagrama UML.','small')
add('La revisión visual actual conserva el contenido de la corrección y aproxima tamaños, tipografía y distribución al original. La validación automática comprueba referencias, balanceo, relaciones y tipos de mensaje. Los hashes SHA-256 permiten verificar que los doce originales no cambiaron. Esto no equivale a una aprobación de la cátedra ni a la entrega de los puntos pendientes.','small')

def footer(canvas,doc):
    canvas.saveState()
    canvas.setStrokeColor(HexColor('#cdd5db'));canvas.line(46,43,A4[0]-46,43)
    canvas.setFont('Arial',8);canvas.setFillColor(MUTED)
    canvas.drawString(46,29,'CAJERO AUTOMÁTICO  |  Revisión de TrabajoCorregido')
    canvas.drawRightString(A4[0]-46,29,str(doc.page))
    canvas.restoreState()
